using NUnit.Framework;

[TestFixture]
public class HasPairWithTargetSumTests
{
    [TestCase(new[] { 1, 2, 4, 6, 10 }, 8, true)]
    [TestCase(new[] { 1, 2, 4, 6, 10 }, 15, false)]
    public void Checks_For_Pair(int[] nums, int target, bool expected)
    {
        Assert.That(HasPairWithTargetSum(nums, target), Is.EqualTo(expected));
    }

    private bool HasPairWithTargetSum(int[] nums, int target)
    {
        int left = 0;
        int right = nums.Length - 1;

        while (left < right)
        {
            int sum = nums[left] + nums[right];

            if (sum == target)
                return true;

            if (sum < target)
                left++;
            else
                right--;
        }

        return false;
    }
}
